import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import './Login.css';

function Login() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();
    window.location.href = '/choose-role';
  };

  return (
    <div className="login-page">
      <div className="login-container">
        <div className="login-header">
          <h1>WORKIE</h1>
          <p className="subtitle">Easy Work From Home</p>
        </div>
        <h2>Selamat Datang!</h2>
        <p className="description">Masuk untuk mulai merekrut atau mencari kerja instan.</p>
        <form className="login-form" onSubmit={handleSubmit}>
          <div className="form-group">
            <label>Nomor HP atau Email</label>
            <input type="text" placeholder="Contoh: +62812345678" value={email} onChange={(e) => setEmail(e.target.value)} />
          </div>
          <div className="form-group">
            <label>Kata Sandi</label>
            <input type="password" placeholder="Masukkan kata sandi Anda" value={password} onChange={(e) => setPassword(e.target.value)} />
          </div>
          <div className="forgot-password"><Link to="/">Lupa Kata Sandi?</Link></div>
          <button type="submit" className="btn-primary">Masuk</button>
        </form>
        <div className="register-link"><Link to="/register">Daftar Akun Baru</Link></div>
        <div className="social-login">
          <p>Atau masuk dengan</p>
          <div className="social-buttons">
            <button className="btn-google">G Google</button>
            <button className="btn-apple">© Apple</button>
          </div>
        </div>
        <div className="guest-link"><Link to="/choose-role">Guest</Link></div>
      </div>
    </div>
  );
}

export default Login;
